import io
import struct
import zlib
from pathlib import Path

import numpy as np
import pytest
from PIL import Image

from qc_preprocess import MAX_PIXELS, InvalidImageError, load_image


def encode(img: Image.Image, fmt: str, **kwargs: object) -> bytes:
    buf = io.BytesIO()
    img.save(buf, fmt, **kwargs)
    return buf.getvalue()


def pattern_image(width: int = 64, height: int = 48) -> Image.Image:
    """Deterministic RGB test image generated by a fixed formula."""
    y, x = np.mgrid[0:height, 0:width]
    arr = np.stack(
        [(x * 7 + y * 3) % 256, (x * y) % 256, (255 - x * 4 + y * 5) % 256], axis=-1
    ).astype(np.uint8)
    return Image.fromarray(arr, "RGB")


def _png_chunk(kind: bytes, data: bytes) -> bytes:
    crc = zlib.crc32(kind + data) & 0xFFFFFFFF
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", crc)


def png_header_only(width: int, height: int) -> bytes:
    """A PNG whose IHDR declares ``width x height`` but carries no pixel data."""
    ihdr = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + _png_chunk(b"IHDR", ihdr) + _png_chunk(b"IEND", b"")


def test_invalid_image_error_is_value_error() -> None:
    assert issubclass(InvalidImageError, ValueError)


@pytest.mark.parametrize("fmt", ["JPEG", "PNG"])
def test_load_accepted_formats(fmt: str) -> None:
    img = load_image(encode(pattern_image(), fmt))
    assert img.mode == "RGB"
    assert img.size == (64, 48)


def test_png_is_lossless() -> None:
    src = pattern_image()
    assert load_image(encode(src, "PNG")).tobytes() == src.tobytes()


def test_load_from_path(tmp_path: Path) -> None:
    path = tmp_path / "photo.png"
    path.write_bytes(encode(pattern_image(), "PNG"))
    assert load_image(path).size == (64, 48)


def test_content_not_extension_decides(tmp_path: Path) -> None:
    path = tmp_path / "photo.jpg"
    path.write_bytes(encode(pattern_image(), "PNG"))
    assert load_image(path).mode == "RGB"
    bad = tmp_path / "fake.png"
    bad.write_bytes(b"not an image")
    with pytest.raises(InvalidImageError):
        load_image(bad)


def test_missing_path() -> None:
    with pytest.raises(FileNotFoundError):
        load_image(Path("nao_existe.jpg"))


def test_wrong_type() -> None:
    with pytest.raises(TypeError):
        load_image("photo.jpg")  # type: ignore[arg-type]


@pytest.mark.parametrize("orientation,size", [(1, (40, 20)), (3, (40, 20)), (6, (20, 40))])
def test_exif_orientation_applied(orientation: int, size: tuple[int, int]) -> None:
    exif = Image.Exif()
    exif[0x0112] = orientation
    data = encode(Image.new("RGB", (40, 20), (200, 10, 10)), "JPEG", exif=exif.tobytes())
    img = load_image(data)
    assert img.size == size
    assert img.mode == "RGB"
    assert img.getexif().get(0x0112, 1) == 1  # orientation consumed (or already upright)


@pytest.mark.parametrize("mode", ["RGBA", "L", "P", "LA", "1"])
def test_png_modes_converted_to_rgb(mode: str) -> None:
    img = load_image(encode(pattern_image().convert(mode), "PNG"))
    assert img.mode == "RGB"


def test_grayscale_jpeg_converted_to_rgb() -> None:
    assert load_image(encode(pattern_image().convert("L"), "JPEG")).mode == "RGB"


def _gif() -> bytes:
    return encode(Image.new("RGB", (10, 10), (1, 2, 3)), "GIF")


def _truncated_jpeg() -> bytes:
    data = encode(pattern_image(640, 480), "JPEG", quality=95)
    return data[: len(data) // 2]


def _truncated_png() -> bytes:
    data = encode(pattern_image(640, 480), "PNG")
    return data[: len(data) // 2]


@pytest.mark.parametrize(
    "data_factory",
    [
        lambda: b"",
        lambda: b"not an image",
        _truncated_jpeg,
        _truncated_png,
        _gif,
        lambda: encode(Image.new("RGB", (10, 10)), "BMP"),
        lambda: encode(Image.new("RGB", (10, 10)), "WEBP"),
        lambda: png_header_only(8000, 8000),
        lambda: png_header_only(MAX_PIXELS + 1, 1),
        lambda: png_header_only(20000, 20000),  # above Pillow's own bomb threshold
    ],
    ids=[
        "empty",
        "text",
        "truncated-jpeg",
        "truncated-png",
        "gif",
        "bmp",
        "webp",
        "8000x8000",
        "limit+1",
        "pillow-bomb",
    ],
)
def test_invalid_images(data_factory) -> None:
    with pytest.raises(InvalidImageError):
        load_image(data_factory())


def test_pixel_limit_is_inclusive() -> None:
    # Exactly MAX_PIXELS passes the header check (it then fails only because there is no data).
    with pytest.raises(InvalidImageError, match="cannot decode"):
        load_image(png_header_only(MAX_PIXELS // 8000, 8000))


# --- MemoryError is not an invalid image (r1 review RV-07) -------------------------------------


@pytest.mark.parametrize("target", ["exif_transpose", "convert"])
def test_memory_error_during_normalization_propagates(
    monkeypatch: pytest.MonkeyPatch, target: str
) -> None:
    def out_of_memory(*_args: object, **_kwargs: object) -> Image.Image:
        raise MemoryError

    if target == "exif_transpose":
        monkeypatch.setattr("qc_preprocess.image.ImageOps.exif_transpose", out_of_memory)
    else:
        monkeypatch.setattr(Image.Image, "convert", out_of_memory)
    with pytest.raises(MemoryError):
        load_image(encode(pattern_image(), "PNG"))


def test_other_normalization_failure_is_invalid_image(monkeypatch: pytest.MonkeyPatch) -> None:
    def broken_exif(*_args: object, **_kwargs: object) -> Image.Image:
        raise KeyError("bad EXIF")

    monkeypatch.setattr("qc_preprocess.image.ImageOps.exif_transpose", broken_exif)
    with pytest.raises(InvalidImageError):
        load_image(encode(pattern_image(), "PNG"))
